```ts
export function createPulse(manager: AnimationManager, button: { scale: number }): () => void {
    let elapsed = -1; // -1 means not started
    const UP_DURATION = 0.2;
    const DOWN_DURATION = 0.2;
    const TOTAL_DURATION = UP_DURATION + DOWN_DURATION;

    const task = createAnimationTask((mgr, deltaMs) => {
        if (elapsed < 0) return; // not started
        elapsed += deltaMs / 1000;
        if (elapsed >= TOTAL_DURATION) {
            button.scale = 1;
            elapsed = -1;
            return;
        }
        if (elapsed < UP_DURATION) {
            button.scale = 1 + 0.5 * (elapsed / UP_DURATION);
        } else {
            const t = (elapsed - UP_DURATION) / DOWN_DURATION;
            button.scale = 1.5 - 0.5 * t;
        }
    });

    addAnimationTask(manager, task);

    return () => {
        elapsed = 0;
    };
}
```

